#pragma once

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

// The C base types, laid out as HAMR computes them
_Static_assert(sizeof(bool) == 1, "bool: memory layout differs from HAMR's");
_Static_assert(_Alignof(bool) == 1, "bool: memory layout differs from HAMR's");

_Static_assert(sizeof(char) == 1, "char: memory layout differs from HAMR's");
_Static_assert(_Alignof(char) == 1, "char: memory layout differs from HAMR's");

_Static_assert(sizeof(int8_t) == 1, "int8_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(int8_t) == 1, "int8_t: memory layout differs from HAMR's");

_Static_assert(sizeof(int16_t) == 2, "int16_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(int16_t) == 2, "int16_t: memory layout differs from HAMR's");

_Static_assert(sizeof(int32_t) == 4, "int32_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(int32_t) == 4, "int32_t: memory layout differs from HAMR's");

_Static_assert(sizeof(int64_t) == 8, "int64_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(int64_t) == 8, "int64_t: memory layout differs from HAMR's");

_Static_assert(sizeof(uint8_t) == 1, "uint8_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(uint8_t) == 1, "uint8_t: memory layout differs from HAMR's");

_Static_assert(sizeof(uint16_t) == 2, "uint16_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(uint16_t) == 2, "uint16_t: memory layout differs from HAMR's");

_Static_assert(sizeof(uint32_t) == 4, "uint32_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(uint32_t) == 4, "uint32_t: memory layout differs from HAMR's");

_Static_assert(sizeof(uint64_t) == 8, "uint64_t: memory layout differs from HAMR's");
_Static_assert(_Alignof(uint64_t) == 8, "uint64_t: memory layout differs from HAMR's");

_Static_assert(sizeof(float) == 4, "float: memory layout differs from HAMR's");
_Static_assert(_Alignof(float) == 4, "float: memory layout differs from HAMR's");

_Static_assert(sizeof(double) == 8, "double: memory layout differs from HAMR's");
_Static_assert(_Alignof(double) == 8, "double: memory layout differs from HAMR's");


// Validity of a value read from shared memory (D6).  Only bool, and the enums and the
// records and arrays containing them, have invalid bit patterns; the rest are always
// valid.  A bool is read as a byte, since reading a bool object that holds neither 0 nor
// 1 is itself undefined.
static inline bool bool_is_valid(const bool *v) { return *(const uint8_t *) v <= 1; }
static inline bool char_is_valid(const char *v) { (void) v; return true; }
static inline bool int8_t_is_valid(const int8_t *v) { (void) v; return true; }
static inline bool int16_t_is_valid(const int16_t *v) { (void) v; return true; }
static inline bool int32_t_is_valid(const int32_t *v) { (void) v; return true; }
static inline bool int64_t_is_valid(const int64_t *v) { (void) v; return true; }
static inline bool uint8_t_is_valid(const uint8_t *v) { (void) v; return true; }
static inline bool uint16_t_is_valid(const uint16_t *v) { (void) v; return true; }
static inline bool uint32_t_is_valid(const uint32_t *v) { (void) v; return true; }
static inline bool uint64_t_is_valid(const uint64_t *v) { (void) v; return true; }
static inline bool float_is_valid(const float *v) { (void) v; return true; }
static inline bool double_is_valid(const double *v) { (void) v; return true; }

typedef struct data_1_prod_2_cons_array_struct_i {
  int32_t currentEvent;
  int32_t totalEventsSent;
} data_1_prod_2_cons_array_struct_i;

_Static_assert(sizeof(data_1_prod_2_cons_array_struct_i) == 8, "data_1_prod_2_cons_array_struct_i: memory layout differs from HAMR's");
_Static_assert(_Alignof(data_1_prod_2_cons_array_struct_i) == 4, "data_1_prod_2_cons_array_struct_i: memory layout differs from HAMR's");
_Static_assert(offsetof(data_1_prod_2_cons_array_struct_i, currentEvent) == 0, "data_1_prod_2_cons_array_struct_i: memory layout differs from HAMR's");
_Static_assert(offsetof(data_1_prod_2_cons_array_struct_i, totalEventsSent) == 4, "data_1_prod_2_cons_array_struct_i: memory layout differs from HAMR's");

static inline bool data_1_prod_2_cons_array_struct_i_is_valid(const data_1_prod_2_cons_array_struct_i *v) {
  return int32_t_is_valid(&v->currentEvent) &&
                  int32_t_is_valid(&v->totalEventsSent);
}

typedef struct hamr_SchedState {
  uint32_t last_yielded_ch;
  uint32_t outstanding;
  uint32_t current_timeslice;
} hamr_SchedState;

_Static_assert(sizeof(hamr_SchedState) == 12, "hamr_SchedState: memory layout differs from HAMR's");
_Static_assert(_Alignof(hamr_SchedState) == 4, "hamr_SchedState: memory layout differs from HAMR's");
_Static_assert(offsetof(hamr_SchedState, last_yielded_ch) == 0, "hamr_SchedState: memory layout differs from HAMR's");
_Static_assert(offsetof(hamr_SchedState, outstanding) == 4, "hamr_SchedState: memory layout differs from HAMR's");
_Static_assert(offsetof(hamr_SchedState, current_timeslice) == 8, "hamr_SchedState: memory layout differs from HAMR's");

static inline bool hamr_SchedState_is_valid(const hamr_SchedState *v) {
  return uint32_t_is_valid(&v->last_yielded_ch) &&
                  uint32_t_is_valid(&v->outstanding) &&
                  uint32_t_is_valid(&v->current_timeslice);
}

#define hamr_ScheduleChannels_DIM_0 128

typedef uint32_t hamr_ScheduleChannels [hamr_ScheduleChannels_DIM_0];

#define hamr_ScheduleChannels_BYTE_SIZE (sizeof(hamr_ScheduleChannels))

_Static_assert(sizeof(hamr_ScheduleChannels) == 512, "hamr_ScheduleChannels: memory layout differs from HAMR's");
_Static_assert(_Alignof(hamr_ScheduleChannels) == 4, "hamr_ScheduleChannels: memory layout differs from HAMR's");


static inline bool hamr_ScheduleChannels_is_valid(const hamr_ScheduleChannels *v) {
  for (size_t i = 0; i < hamr_ScheduleChannels_DIM_0; i++) {
    if (!uint32_t_is_valid(&(*v)[i])) {
      return false;
    }
  }
  return true;
}

#define hamr_ScheduleTimeslices_DIM_0 128

typedef uint64_t hamr_ScheduleTimeslices [hamr_ScheduleTimeslices_DIM_0];

#define hamr_ScheduleTimeslices_BYTE_SIZE (sizeof(hamr_ScheduleTimeslices))

_Static_assert(sizeof(hamr_ScheduleTimeslices) == 1024, "hamr_ScheduleTimeslices: memory layout differs from HAMR's");
_Static_assert(_Alignof(hamr_ScheduleTimeslices) == 8, "hamr_ScheduleTimeslices: memory layout differs from HAMR's");


static inline bool hamr_ScheduleTimeslices_is_valid(const hamr_ScheduleTimeslices *v) {
  for (size_t i = 0; i < hamr_ScheduleTimeslices_DIM_0; i++) {
    if (!uint64_t_is_valid(&(*v)[i])) {
      return false;
    }
  }
  return true;
}

#define hamr_ScheduleUserPartitions_DIM_0 128

typedef bool hamr_ScheduleUserPartitions [hamr_ScheduleUserPartitions_DIM_0];

#define hamr_ScheduleUserPartitions_BYTE_SIZE (sizeof(hamr_ScheduleUserPartitions))

_Static_assert(sizeof(hamr_ScheduleUserPartitions) == 128, "hamr_ScheduleUserPartitions: memory layout differs from HAMR's");
_Static_assert(_Alignof(hamr_ScheduleUserPartitions) == 1, "hamr_ScheduleUserPartitions: memory layout differs from HAMR's");


static inline bool hamr_ScheduleUserPartitions_is_valid(const hamr_ScheduleUserPartitions *v) {
  for (size_t i = 0; i < hamr_ScheduleUserPartitions_DIM_0; i++) {
    if (!bool_is_valid(&(*v)[i])) {
      return false;
    }
  }
  return true;
}

#define data_1_prod_2_cons_array_ArrayOfStruct_DIM_0 10

typedef data_1_prod_2_cons_array_struct_i data_1_prod_2_cons_array_ArrayOfStruct [data_1_prod_2_cons_array_ArrayOfStruct_DIM_0];

#define data_1_prod_2_cons_array_ArrayOfStruct_BYTE_SIZE (sizeof(data_1_prod_2_cons_array_ArrayOfStruct))

_Static_assert(sizeof(data_1_prod_2_cons_array_ArrayOfStruct) == 80, "data_1_prod_2_cons_array_ArrayOfStruct: memory layout differs from HAMR's");
_Static_assert(_Alignof(data_1_prod_2_cons_array_ArrayOfStruct) == 4, "data_1_prod_2_cons_array_ArrayOfStruct: memory layout differs from HAMR's");


static inline bool data_1_prod_2_cons_array_ArrayOfStruct_is_valid(const data_1_prod_2_cons_array_ArrayOfStruct *v) {
  for (size_t i = 0; i < data_1_prod_2_cons_array_ArrayOfStruct_DIM_0; i++) {
    if (!data_1_prod_2_cons_array_struct_i_is_valid(&(*v)[i])) {
      return false;
    }
  }
  return true;
}

typedef struct hamr_Schedule {
  hamr_ScheduleTimeslices timeslices;
  hamr_ScheduleChannels timeslice_ch;
  hamr_ScheduleUserPartitions is_user_partition;
  uint32_t num_timeslices;
} hamr_Schedule;

_Static_assert(sizeof(hamr_Schedule) == 1672, "hamr_Schedule: memory layout differs from HAMR's");
_Static_assert(_Alignof(hamr_Schedule) == 8, "hamr_Schedule: memory layout differs from HAMR's");
_Static_assert(offsetof(hamr_Schedule, timeslices) == 0, "hamr_Schedule: memory layout differs from HAMR's");
_Static_assert(offsetof(hamr_Schedule, timeslice_ch) == 1024, "hamr_Schedule: memory layout differs from HAMR's");
_Static_assert(offsetof(hamr_Schedule, is_user_partition) == 1536, "hamr_Schedule: memory layout differs from HAMR's");
_Static_assert(offsetof(hamr_Schedule, num_timeslices) == 1664, "hamr_Schedule: memory layout differs from HAMR's");

static inline bool hamr_Schedule_is_valid(const hamr_Schedule *v) {
  return hamr_ScheduleTimeslices_is_valid(&v->timeslices) &&
                  hamr_ScheduleChannels_is_valid(&v->timeslice_ch) &&
                  hamr_ScheduleUserPartitions_is_valid(&v->is_user_partition) &&
                  uint32_t_is_valid(&v->num_timeslices);
}

#pragma once

#include <stdint.h>

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

typedef _Atomic uintmax_t sb_event_counter_t;

/*
